Analisando a estrutura do problema, podemos modelar as transições através de um grafo direcionado onde cada estado é um par ordenado $(u, v)$, representando uma ciclovia percorrida de $u$ para $v$. 

A partir do estado $(u, v)$, podemos nos mover para o estado $(v, w)$ se $(v, w)$ for uma ciclovia e $w > u$. Note que:
$$(u + v) < (v + w) \iff u < w$$
Isso significa que a cada passo ao longo do caminho, a soma dos vértices da aresta $u + v$ **aumenta estritamente**. Consequentemente, o grafo de estados é garantidamente um DAG (Grafo Acíclico Direcionado) e uma ordem topológica válida pode ser obtida simplesmente ordenando os estados $(u, v)$ em ordem decrescente de $u + v$.

Com $N \le 10^5$ e $M \le 5 \times 10^5$, o número total de estados direcionados é $2M \le 10^6$. Ao processar as arestas em ordem decrescente da soma $u + v$, podemos manter para cada vértice $v$ o valor máximo de $dp(v, w)$ para $w > u$ de forma eficiente.

Abaixo está a solução completa e eficiente em Java:

```java
import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) b = readByte();
            if (b == -1) return -1;
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int m = scanner.nextInt();

        int[] u = new int[m];
        int[] v = new int[m];
        int[] degree = new int[n + 1];

        for (int i = 0; i < m; i++) {
            u[i] = scanner.nextInt();
            v[i] = scanner.nextInt();
            degree[u[i]]++;
            degree[v[i]]++;
        }

        // Construir a lista de adjacência (grafo direcionado contendo ambos os sentidos)
        int[] head = new int[n + 1];
        Arrays.fill(head, -1);
        int totalEdges = 2 * m;
        int[] to = new int[totalEdges];
        int[] next = new int[totalEdges];
        int edgeCount = 0;

        for (int i = 0; i < m; i++) {
            int a = u[i];
            int b = v[i];

            to[edgeCount] = b;
            next[edgeCount] = head[a];
            head[a] = edgeCount++;

            to[edgeCount] = a;
            next[edgeCount] = head[b];
            head[b] = edgeCount++;
        }

        // Para ordenar os vizinhos de cada nó em ordem crescente
        // Vetores adj e posEdge armazenarão os vizinhos ordenados e o índice da aresta correspondente
        int[] adjHead = new int[n + 2];
        for (int i = 1; i <= n; i++) {
            adjHead[i + 1] = adjHead[i] + degree[i];
        }

        int[] curPtr = adjHead.clone();
        int[] adj = new int[totalEdges];
        int[] edgeId = new int[totalEdges];

        for (int i = 1; i <= n; i++) {
            for (int e = head[i]; e != -1; e = next[e]) {
                int w = to[e];
                int p = curPtr[i]++;
                adj[p] = w;
                edgeId[p] = e;
            }
        }

        // Ordenar os vizinhos de cada vértice por radix/counting sort ou ordenação simples
        for (int i = 1; i <= n; i++) {
            int start = adjHead[i];
            int end = adjHead[i + 1];
            // Para pequenos tamanhos de vizinhança ou geral:
            // Podemos usar um algoritmo de ordenação para emparelhar (adj, edgeId)
            quickSort(adj, edgeId, start, end - 1);
        }

        // Agora, para o DAG, precisamos ordenar todas as 2*M arestas direcionadas em ordem decrescente de (origem + destino)
        // Como soma = u + v varia de 3 até 2*N, podemos usar Counting Sort para O(M)
        int maxSum = 2 * n;
        int[] count = new int[maxSum + 1];

        // edgeIndexOrig[e] -> u = from do edge e
        int[] from = new int[totalEdges];
        for (int i = 1; i <= n; i++) {
            for (int e = head[i]; e != -1; e = next[e]) {
                from[e] = i;
                count[i + to[e]]++;
            }
        }

        int[] sumHead = new int[maxSum + 2];
        for (int s = maxSum; s >= 1; s--) {
            sumHead[s] = sumHead[s + 1] + count[s];
        }

        int[] sortedEdges = new int[totalEdges];
        int[] curSumPtr = sumHead.clone();

        for (int e = 0; e < totalEdges; e++) {
            int s = from[e] + to[e];
            sortedEdges[curSumPtr[s]++] = e;
        }

        // dp[e] = comprimento máximo do caminho começando com a aresta e
        int[] dp = new int[totalEdges];
        // maxSuf[p] guardará o maior dp para adjacências em adjHead[v]
        int[] maxSuf = new int[totalEdges];

        // Para busca binária rápida no array de adjacentes
        // sortedEdges já está em ordem decrescente de soma u + v
        for (int idx = 0; idx < totalEdges; idx++) {
            int e = sortedEdges[idx];
            int uNode = from[e];
            int vNode = to[e];

            // A transição de (u, v) vai para (v, w) com w > u
            // Procuramos o primeiro w em adj[v] tal que w > u
            int start = adjHead[vNode];
            int end = adjHead[vNode + 1] - 1;
            int firstW = -1;

            int low = start, high = end;
            while (low <= high) {
                int mid = (low + high) >>> 1;
                if (adj[mid] > uNode) {
                    firstW = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }

            int bestNext = 1; // Se não houver w > u, o caminho é apenas (u, v) que tem tamanho 2
            if (firstW != -1) {
                bestNext = Math.max(bestNext, maxSuf[firstW]);
            }

            dp[e] = 1 + bestNext;

            // Encontrar onde está a aresta 'e' na lista de adjacência de uNode
            // Como adj[uNode] está ordenado, encontramos vNode via busca binária
            low = adjHead[uNode];
            high = adjHead[uNode + 1] - 1;
            int pos = -1;
            while (low <= high) {
                int mid = (low + high) >>> 1;
                if (adj[mid] == vNode) {
                    pos = mid;
                    break;
                } else if (adj[mid] < vNode) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            // Atualizar o sufixo máximo para uNode
            // maxSuf[k] = max(dp correspondente a adj[k], maxSuf[k+1])
            // Note que estamos computando em ordem decrescente de soma, mas maxSuf[pos]
            // precisa ser max(dp[e], maxSuf[pos + 1])
            // Contudo, maxSuf[pos] depende dos elementos maiores que vNode também.
            // Para garantir a corretude, atualizamos o maxSuf propagando para trás a partir de pos:
            updateSuffix(maxSuf, adjHead[uNode], pos, dp[e]);
        }

        // A resposta para o vértice i é max(1, max_{e saindo de i} dp[e])
        int[] ans = new int[n + 1];
        Arrays.fill(ans, 1);

        for (int e = 0; e < totalEdges; e++) {
            int uNode = from[e];
            if (dp[e] > ans[uNode]) {
                ans[uNode] = dp[e];
            }
        }

        PrintWriter out = new PrintWriter(System.out);
        for (int i = 1; i <= n; i++) {
            out.print(ans[i]);
            if (i < n) out.print(" ");
        }
        out.println();
        out.flush();
    }

    private static void updateSuffix(int[] maxSuf, int start, int pos, int val) {
        for (int i = pos; i >= start; i--) {
            if (val > maxSuf[i]) {
                maxSuf[i] = val;
            } else {
                break;
            }
        }
    }

    private static void quickSort(int[] a, int[] b, int l, int r) {
        if (l >= r) return;
        int pivot = a[l + (r - l) / 2];
        int i = l, j = r;
        while (i <= j) {
            while (a[i] < pivot) i++;
            while (a[j] > pivot) j--;
            if (i <= j) {
                int tmpA = a[i]; a[i] = a[j]; a[j] = tmpA;
                int tmpB = b[i]; b[i] = b[j]; b[j] = tmpB;
                i++;
                j--;
            }
        }
        quickSort(a, b, l, j);
        quickSort(a, b, i, r);
    }
}
